        if isinstance(p, (list, tuple)) and len(p) >= 2:
            x, y = int(p[0]), int(p[1])
            if 0 <= x < w and 0 <= y < h:
                obstacles.add((x, y))

    targets = []
    uc = observation.get("unclaimed_cells") or []
    if uc:
        for p in uc:
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                x, y = int(p[0]), int(p[1])
                if 0 <= x < w and 0 <= y < h:
                    targets.append((x, y))
    else:
        st = observation.get("self_territory") or []
        for p in st:
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                x, y = int(p[0]), int(p[1])
                if 0 <= x < w and 0 <= y < h:
                    targets.append((x, y))
        if not targets:
            res = observation.get("resources") or []
            for p in res:
                if isinstance(p, (list, tuple)) and len(p) >= 2:
                    x, y = int(p[0]), int(p[1])
                    if 0 <= x < w and 0 <= y < h:
                        targets.append((x, y))

    def man(a, b, c, d): return abs(a - c) + abs(b - d)
